#include <algorithm>
#include <numeric>
#include <stdexcept>

std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_);
    std::transform(
        result.begin(), result.end(), result.begin(),
        [this](std::size_t c) -> double {
            double s = 0.0;
            for (std::size_t r = 0; r < rows_; ++r) {
                s += at(r, c);
            }
            return std::accumulate(&at(0, c), &at(0, c) + rows_, s);
        });
    return result;
}

